import{_ as a,o as i,c as s,ag as t}from"./chunks/framework.CPvOxTBX.js";const k=JSON.parse('{"title":"Pronunciation and pronunciation packs","description":"","frontmatter":{},"headers":[],"relativePath":"guide/pronunciation.md","filePath":"guide/pronunciation.md","lastUpdated":1793449457000}'),n={name:"guide/pronunciation.md"};function o(d,e,h,r,p,l){return i(),s("div",null,e[0]||(e[0]=[t(`<h1 id="pronunciation-and-pronunciation-packs" tabindex="-1">Pronunciation and pronunciation packs <a class="header-anchor" href="#pronunciation-and-pronunciation-packs" aria-label="Permalink to &quot;Pronunciation and pronunciation packs&quot;">​</a></h1><p>Ciyue can read a word out in two ways: <strong>pronunciation packs</strong> (recordings stored in <code>.mdd</code> or <code>.zip</code> / <code>.zips</code> files) and <strong>TTS</strong> (the system speech synthesiser).</p><h2 id="three-modes" tabindex="-1">Three modes <a class="header-anchor" href="#three-modes" aria-label="Permalink to &quot;Three modes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mode</th><th>Behaviour</th></tr></thead><tbody><tr><td>Packs first, TTS as fallback</td><td>Play a recording if the packs have one, otherwise read the word aloud</td></tr><tr><td>Packs only</td><td>Play recordings only; stay silent when none matches</td></tr><tr><td>TTS only</td><td>Ignore the packs and always read the word aloud</td></tr></tbody></table><p>Packs are added in Settings → Audio → Pronunciation Packs. You can add several and drag them to change their priority.</p><h2 id="pack-formats" tabindex="-1">Pack formats <a class="header-anchor" href="#pack-formats" aria-label="Permalink to &quot;Pack formats&quot;">​</a></h2><p>A pack can be an <code>.mdd</code> file or a plain zip — with the <code>.zip</code> or <code>.zips</code> extension (the latter is GoldenDict&#39;s extension for pronunciation archives; the file itself is a plain zip).</p><table tabindex="0"><thead><tr><th>Format</th><th>To change one file inside</th></tr></thead><tbody><tr><td><code>.mdd</code></td><td>MDict&#39;s private format: unpack and repack with MdxBuilder or mdict-utils</td></tr><tr><td><code>.zip</code> / <code>.zips</code></td><td>Plain zip: replace files with whatever archiver you already have</td></tr></tbody></table><p>When you need to swap one recording, the zip form is far less work — extract, replace, re-zip, no dedicated tools. Both forms can be mixed, and drag-to-reorder priority treats them the same.</p><h2 id="which-formats-play" tabindex="-1">Which formats play <a class="header-anchor" href="#which-formats-play" aria-label="Permalink to &quot;Which formats play&quot;">​</a></h2><p>What decides this is the <strong>system decoder</strong> (Android uses MediaPlayer), not Ciyue.</p><table tabindex="0"><thead><tr><th>Format</th><th>Status</th></tr></thead><tbody><tr><td>MP3</td><td>The safest choice</td></tr><tr><td>WAV (PCM)</td><td>Fine; ADPCM, μ-law and A-law depend on the device</td></tr><tr><td>AAC / M4A</td><td>Supported natively, both raw ADTS (<code>.aac</code>) and MP4</td></tr><tr><td>OGG Vorbis</td><td>Supported</td></tr><tr><td>Ogg Speex (<code>.spx</code>)</td><td><strong>Not supported</strong> — Android has no Speex decoder</td></tr><tr><td>Opus</td><td>Depends on the system version and container; Ogg Opus is unreliable on older releases</td></tr></tbody></table><p><code>.spx</code> is the format most likely to trip you up.</p><p>WAV is the same story: the extension says nothing about what is inside. The <code>fmt</code> field can be PCM, ADPCM, μ-law, or <strong>MP3 data in a WAV wrapper</strong> (<code>fmt=0x55</code>). The last one plays fine on the device we tested — the system hands it to the MP3 decoder — so a <code>.wav</code> suffix is not a reason to suspect the format. Check the log for <code>Playing sound</code> first, as described in the next section.</p><h2 id="when-a-tap-produces-no-sound" tabindex="-1">When a tap produces no sound <a class="header-anchor" href="#when-a-tap-produces-no-sound" aria-label="Permalink to &quot;When a tap produces no sound&quot;">​</a></h2><p>Two cases:</p><p><strong>A snackbar says this device cannot play the dictionary&#39;s audio format.</strong> The resource was found and handed to the decoder, which cannot handle it. Convert it, as described below.</p><p><strong>Nothing happens at all, not even a message.</strong> The <code>sound://</code> link does not point at an existing resource — the name in the entry does not match anything in the <code>.mdd</code> (for a StarDict dictionary, in its <code>res/</code> folder or resource archive), or the dictionary ships no audio. Confirm whether the tap reached playback with <code>adb logcat | grep -E &quot;Playing sound|Failed to play audio bytes&quot;</code>.</p><h2 id="converting-audio-the-device-cannot-play" tabindex="-1">Converting audio the device cannot play <a class="header-anchor" href="#converting-audio-the-device-cannot-play" aria-label="Permalink to &quot;Converting audio the device cannot play&quot;">​</a></h2><p>The key rule: <strong>if you are not going to edit the <code>.mdx</code>, do not rename anything inside the <code>.mdd</code></strong> (for a StarDict dictionary, anything in <code>res/</code> or its resource archive). Entries reference the files as <code>sound://ID1234.spx</code>, so changing an extension breaks the link and turns &quot;silent&quot; into &quot;nothing happens at all&quot;.</p><p>Ogg Speex and Ogg Vorbis share the same container, so the contents of a <code>.spx</code> file can be replaced with Vorbis while the file keeps its <code>.spx</code> name. Container, extension and the MIME type Ciyue passes (<code>audio/ogg</code>) all stay consistent, and Android decodes it normally.</p><h3 id="_1-unpack" tabindex="-1">1. Unpack <a class="header-anchor" href="#_1-unpack" aria-label="Permalink to &quot;1. Unpack&quot;">​</a></h3><p>With a GUI, use MdxExport (Windows) and export the <code>.mdd</code> to a folder. From a shell, use <code>mdict-utils</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mdict-utils</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mdict-utils</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mddunpack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dictionary.mdd</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # split archives: dictionary.1.mdd, dictionary.2.mdd, …</span></span></code></pre></div><blockquote><p>Some dictionaries keep images and audio in the same <code>.mdd</code>. Keep every file after unpacking; convert only the audio.</p></blockquote><h3 id="_2-convert-in-place-keeping-file-names" tabindex="-1">2. Convert in place, keeping file names <a class="header-anchor" href="#_2-convert-in-place-keeping-file-names" aria-label="Permalink to &quot;2. Convert in place, keeping file names&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Replace Ogg Speex with Ogg Vorbis, writing back to the same .spx name.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">find</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -type</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> f</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -iname</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;*.spx&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -print0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> while</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> IFS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> read</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> f</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">do</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  ffmpeg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -nostdin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -loglevel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> error</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    -c:a</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> libvorbis</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -q:a</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -ac</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -ar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 22050</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ogg</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">f</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">%</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">spx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}.tmp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">f</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">%</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">spx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}.tmp&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">done</span></span></code></pre></div><p>Notes on the flags:</p><ul><li><code>-f ogg</code> is required; without it ffmpeg refuses to pick a container for a <code>.spx</code> output name</li><li><code>-ac 1 -ar 22050</code> is plenty for a single word, and keeps the size roughly within twice the original</li><li><code>-q:a 3</code> is a comfortable Vorbis quality for speech</li></ul><p>Spot-check one file afterwards:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> some-file.spx</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # should report &quot;Ogg data, Vorbis audio&quot;</span></span></code></pre></div><h3 id="_3-repack" tabindex="-1">3. Repack <a class="header-anchor" href="#_3-repack" aria-label="Permalink to &quot;3. Repack&quot;">​</a></h3><p>With a GUI, use MdxBuilder with type <strong>MDD</strong>, point the source at the unpacked folder and write the same <code>.mdd</code> name. From a shell:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mdict-utils</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mddpack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./unpacked</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dictionary.mdd</span></span></code></pre></div><p>Repack split volumes separately (<code>.1.mdd</code>, <code>.2.mdd</code>, …). The number of volumes does not have to match the original, but keep the files of a volume together.</p><h3 id="_4-put-it-back-and-re-add-the-pack" tabindex="-1">4. Put it back and re-add the pack <a class="header-anchor" href="#_4-put-it-back-and-re-add-the-pack" aria-label="Permalink to &quot;4. Put it back and re-add the pack&quot;">​</a></h3><p>Replace the original <code>.mdd</code> (or place it anywhere), then remove the old pack in Settings → Audio → Pronunciation Packs, add the new one, and try a word.</p><h2 id="common-traps" tabindex="-1">Common traps <a class="header-anchor" href="#common-traps" aria-label="Permalink to &quot;Common traps&quot;">​</a></h2><ul><li><strong>Renamed extensions, untouched <code>.mdx</code></strong>: the <code>sound://…spx</code> links inside the <code>.mdx</code> do not follow. Keep the extension (the Vorbis trick above) or rebuild the <code>.mdx</code> too.</li><li><strong>Converting only some files</strong>: a dictionary may mix <code>.spx</code> and <code>.mp3</code>. Check first with <code>find . -type f | sed &#39;s/.*\\.//&#39; | sort | uniq -c</code>.</li><li><strong>Path separators</strong>: resource paths inside an MDD can be <code>\\img\\a.spx</code> or <code>/img/a.spx</code>. Keep them exactly as they were when repacking.</li><li><strong>Packs are not the same as entry audio</strong>: recordings that ship inside a dictionary play through its <code>sound://</code> links with no setup — from the <code>.mdd</code> for an MDX dictionary, from <code>res/</code> or the resource archives (<code>res.zip</code>, <code>&lt;name&gt;.res.zip</code>, <code>res/res.zip</code>) for a StarDict one. Adding a pack is for the separate &quot;read any looked-up word aloud&quot; feature.</li></ul>`,39)]))}const g=a(n,[["render",o]]);export{k as __pageData,g as default};
